import { readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import path from "node:path";
import { emitModels, writeGenerated } from "./lib/contract-codegen.mjs";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const contract = JSON.parse(
  await readFile(path.join(root, "contracts/workforce-benefits.json"), "utf8"),
);
const models = emitModels(contract.models);
let go =
  '// Code generated by scripts/generate-workforce-benefits.mjs; DO NOT EDIT.\npackage workforce\n\nimport("time";"github.com/google/uuid")\n\n';
let ts = '// Generated by scripts/generate-workforce-benefits.mjs.\nimport { z } from "zod";\n\n';
ts += `export const BENEFIT_PLAN_KINDS=${JSON.stringify(contract.plan_kinds)} as const;\n`;
await writeGenerated(
  root,
  "backend/internal/modules/workforce/benefits_types.go",
  go + models.go,
  "packages/api/src/benefits-contract.ts",
  ts + models.ts,
  "benefits",
);
